    // Registro modular de ventanas para los botones de la herramienta
    const TOOL_WINDOWS = {
        home: { title: 'Terminal Home & Node.js', handler: () => showTerminalView() },
        search: { title: 'Búsqueda Global en Archivos', handler: (id) => showPlaceholderTool(id, 'Búsqueda Global') },
        warpAi: { title: 'Warp AI Engine & Generador', handler: (id) => showPlaceholderTool(id, 'Warp AI Engine') },
        notebook: { title: 'Cuaderno Interactivo & Markdown', handler: (id) => showPlaceholderTool(id, 'Notebook Interactivo') },
        accordion: { title: 'Estructura & Árbol de Código', handler: (id) => showPlaceholderTool(id, 'Estructura de Carpetas') },
        saxophone: { title: 'Audio & Procesamiento DSP', handler: (id) => showPlaceholderTool(id, 'Audio & DSP Toolkit') },
        plane: { title: 'Deploy & Despliegue Cloud', handler: (id) => showPlaceholderTool(id, 'Cloud Deployment') },
        airplane: { title: 'API Gateway & Storage Controller', handler: () => showApiGatewayWindow() },
        api: { title: 'API Gateway & Storage Controller', handler: () => showApiGatewayWindow() },
        seaport: { title: 'Puerto Marítimo de Datos (LocalStack)', handler: () => showSeaportWindow() },
        potion: { title: 'Compilador & WebAssembly', handler: (id) => showPlaceholderTool(id, 'WASM Compiler') },
        dragon: { title: 'Motor de Inteligencia & Agentes', handler: (id) => showPlaceholderTool(id, 'Engine AI Core') },
        tractor: { title: 'Procesamiento Masivo de Datos', handler: (id) => showPlaceholderTool(id, 'Data Pipeline') },
        settings: { title: 'Configuración & Preferencias', handler: (id) => showPlaceholderTool(id, 'Ajustes de Terminal') }
    };

    let activeToolId = 'home';
    let tabs = [
        { id: 'tab-1', title: 'bash', icon: 'bash', feed: [], history: [], cwd: '~/workspace' }
    ];
    let activeTabId = 'tab-1';
    let tabCounter = 1;
    let historyIndex = -1;

    function getActiveTab() {
        return tabs.find(t => t.id === activeTabId) || tabs[0];
    }

    const WarpTerminal = {
        open() {
            const modal = document.getElementById('tool3Modal') || document.getElementById('warpTerminalModal');
            if (modal) {
                modal.classList.add('open');
                renderTabs();
        WarpTerminal.fetchWorkspaceStatus();
                renderActiveFeed();
                setTimeout(() => {
                    const inp = modal.querySelector('#warpCmdInput') || document.getElementById('warpCmdInput');
                    if (inp) inp.focus();
                }, 100);
            }
        },

        close() {
            const modal1 = document.getElementById('tool3Modal');
            if (modal1) modal1.classList.remove('open');
            const modal2 = document.getElementById('warpTerminalModal');
            if (modal2) modal2.classList.remove('open');
        },

        
        workspaceConfig: null,

        async fetchWorkspaceStatus() {
            try {
                const res = await fetch(l8ApiUrl('api/bash/workspace'));
                if (res.ok) {
                    const data = await res.json();
                    if (data.ok) {
                        this.workspaceConfig = data;
                        this.updateStatusPath(data.display_path || '~/workspace');
                        return data;
                    }
                }
            } catch (e) {
                console.warn('[WarpTerminal] Error al consultar API de workspace:', e);
            }
            return null;
        },

        updateStatusPath(displayPath) {
            document.querySelectorAll('#warpStatusPath').forEach(el => {
                el.textContent = displayPath;
            });
            const curTab = getActiveTab();
            if (curTab) {
                curTab.cwd = displayPath;
            }
        },

        openWorkspaceModal() {
            let overlay = document.getElementById('warpWorkspaceModal');
            if (!overlay) {
                overlay = document.createElement('div');
                overlay.id = 'warpWorkspaceModal';
                overlay.className = 'warp-workspace-modal-overlay';
                overlay.onclick = (e) => {
                    if (e.target === overlay) this.closeWorkspaceModal();
                };
                document.body.appendChild(overlay);
            }

            const cfg = this.workspaceConfig || {
                workspace_path: 'D:/laragon/www/l8/workspace',
                display_path: '~/workspace',
                api_url: '/api/bash/workspace',
                status: 'connected',
                files_count: 0,
                files: []
            };

            const filesHtml = (cfg.files && cfg.files.length) ? cfg.files.map(f => `
                <div class="warp-ws-file-item">
                    <span>${f.is_dir ? '📁 ' : '📄 '} ${escapeHtml(f.name)}</span>
                    <span style="color:#64748B; font-size:11px;">${f.is_dir ? 'directorio' : (f.size + ' B')}</span>
                </div>
            `).join('') : '<div style="padding:10px; color:#64748B; text-align:center;">(Carpeta vacía o sin archivos listados)</div>';

            overlay.innerHTML = `
                <div class="warp-workspace-modal-card">
                    <div class="warp-ws-header">
                        <h3>
                            <span style="display:inline-flex; width:16px; height:16px;">${SVG_ICONS.folder}</span>
                            <span>Carpeta Centralizada y Conexión API</span>
                        </h3>
                        <span class="warp-ws-badge">
                            <span class="warp-ws-badge-dot"></span>
                            <span>API Conectada</span>
                        </span>
                    </div>

                    <div class="warp-ws-body">
                        <div class="warp-ws-stats">
                            <div class="warp-ws-stat-item">
                                <span class="warp-ws-stat-val">${cfg.files_count || (cfg.files ? cfg.files.length : 0)}</span>
                                <span class="warp-ws-stat-lbl">Archivos Centrales</span>
                            </div>
                            <div class="warp-ws-stat-item">
                                <span class="warp-ws-stat-val">Centralizado</span>
                                <span class="warp-ws-stat-lbl">Modo de Almacenamiento</span>
                            </div>
                            <div class="warp-ws-stat-item">
                                <span class="warp-ws-stat-val" style="color:#34D399;">ONLINE</span>
                                <span class="warp-ws-stat-lbl">Estado del Motor</span>
                            </div>
                        </div>

                        <div class="warp-ws-field">
                            <label class="warp-ws-label">Ruta Local / Central de Almacenamiento</label>
                            <input type="text" class="warp-ws-input" id="warpWsInputPath" value="${escapeHtml(cfg.workspace_path || '')}" placeholder="ej: D:/laragon/www/l8/workspace" />
                        </div>

                        <div class="warp-ws-field">
                            <label class="warp-ws-label">Alias en Terminal (Display CWD)</label>
                            <input type="text" class="warp-ws-input" id="warpWsInputDisplay" value="${escapeHtml(cfg.display_path || '~/workspace')}" placeholder="ej: ~/workspace" />
                        </div>

                        <div class="warp-ws-field">
                            <label class="warp-ws-label">Dirección de la API / Endpoint de Conexión</label>
                            <input type="text" class="warp-ws-input" id="warpWsInputApi" value="${escapeHtml(cfg.api_url || '/api/bash/workspace')}" placeholder="ej: /api/bash/workspace o https://api.dominio.com" />
                        </div>

                        <div class="warp-ws-field">
                            <label class="warp-ws-label">Archivos en la Carpeta Central</label>
                            <div class="warp-ws-files-box" id="warpWsFilesBox">
                                ${filesHtml}
                            </div>
                        </div>
                    </div>

                    <div class="warp-ws-footer">
                        <button type="button" class="warp-ws-btn warp-ws-btn-secondary" onclick="WarpTerminal.closeWorkspaceModal()">Cerrar</button>
                        <button type="button" class="warp-ws-btn warp-ws-btn-primary" onclick="WarpTerminal.saveWorkspaceModalConfig()">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path><polyline points="17 21 17 13 7 13 7 21"></polyline><polyline points="7 3 7 8 15 8"></polyline></svg>
                            <span>Guardar y Conectar</span>
                        </button>
                    </div>
                </div>
            `;

            overlay.classList.add('open');
        },

        closeWorkspaceModal() {
            const overlay = document.getElementById('warpWorkspaceModal');
            if (overlay) overlay.classList.remove('open');
        },

        async execApiCmd(cmd) {
            const feed = document.getElementById('warpApiTermFeed');
            if (feed) {
                const line = document.createElement('div');
                line.style.color = '#38BDF8';
                line.textContent = '> ' + cmd;
                feed.appendChild(line);
            }

            try {
                const res = await fetch(l8ApiUrl('api/bash/exec'), {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                        'X-L8-CSRF': '1'
                    },
                    body: JSON.stringify({ command: cmd })
                });
                const data = await res.json();
                if (feed) {
                    const out = document.createElement('div');
                    out.style.color = data.ok ? '#E2E8F0' : '#EF4444';
                    out.style.whiteSpace = 'pre-wrap';
                    out.style.margin = '4px 0 8px 0';
                    out.textContent = data.stdout || data.stderr || data.error || '(Comando ejecutado)';
                    feed.appendChild(out);
                    feed.scrollTop = feed.scrollHeight;
                }
                // Auto-refrescar ventana de API
                showApiGatewayWindow();
            } catch (e) {
                if (feed) {
                    const err = document.createElement('div');
                    err.style.color = '#EF4444';
                    err.textContent = 'Error: ' + e.message;
                    feed.appendChild(err);
                }
            }
        },

        submitApiTerminalInput() {
            const inp = document.getElementById('warpApiTermInput');
            if (!inp) return;
            const cmd = inp.value.trim();
            if (cmd) {
                inp.value = '';
                this.execApiCmd(cmd);
            }
        },

        async saveWorkspaceModalConfig() {
            const pathInp = document.getElementById('warpWsInputPath');
            const dispInp = document.getElementById('warpWsInputDisplay');
            const apiInp = document.getElementById('warpWsInputApi');

            const payload = {
                path: pathInp ? pathInp.value.trim() : '',
                display_path: dispInp ? dispInp.value.trim() : '',
                api_url: apiInp ? apiInp.value.trim() : ''
            };

            try {
                const res = await fetch(l8ApiUrl('api/bash/workspace/connect'), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                if (data.ok) {
                    await this.fetchWorkspaceStatus();
                    this.closeWorkspaceModal();
                    
                    const curTab = getActiveTab();
                    if (curTab) {
                        curTab.feed.push({
                            command: 'workspace connect ' + (payload.api_url || '/api/bash/workspace'),
                            output: 'Carpeta central conectada a la API:\nPath: ' + (payload.path || data.config.workspace_path) + '\nDisplay: ' + (payload.display_path || data.config.display_path),
                            ok: true,
                            time: Date.now()
                        });
                        renderActiveFeed();
                        scrollFeedToBottom();
                    }
                } else {
                    alert('Error al conectar carpeta central: ' + (data.error || 'Desconocido'));
                }
            } catch (e) {
                alert('Error de conexión con la API: ' + e.message);
            }
        },

        registerToolWindow(toolId, config) {
            TOOL_WINDOWS[toolId] = config;
        },

        async executeCommand(cmd) {
            if (!cmd || !cmd.trim()) return;
            const command = cmd.trim();
            const curTab = getActiveTab();

            if (command === 'clear' || command === 'cls') {
                curTab.feed = [];
                curTab.history.push(command);
                historyIndex = curTab.history.length;
                renderActiveFeed();
                return;
            }

            curTab.history.push(command);
            historyIndex = curTab.history.length;

            const feed = document.getElementById('warpTerminalFeed');
            const placeholder = document.getElementById('warpAmbientPlaceholder');
            if (placeholder) {
                placeholder.classList.add('hidden');
                placeholder.style.display = 'none';
            }

            const cwd = curTab.cwd || '~/workspace';
            const block = createBlockElement(command, cwd, true);
            if (feed) feed.appendChild(block);
            scrollFeedToBottom();

            const startTime = performance.now();

            // Interceptación de Comandos del Puerto Marítimo de Datos (Data Seaport CLI)
            if (typeof window !== 'undefined' && window.DataSeaport) {
                try {
                    const seaportResult = await window.DataSeaport.handleCommand(command);
                    if (seaportResult !== null) {
                        const durMs = Math.round(performance.now() - startTime);
                        const statusEl = block.querySelector('.warp-block-status');
                        const statusLbl = block.querySelector('.status-label');
                        const durationEl = block.querySelector('.warp-block-duration');
                        const outputEl = block.querySelector('.warp-block-output');

                        if (statusEl) statusEl.className = 'warp-block-status success';
                        if (statusLbl) statusLbl.textContent = '0';
                        if (durationEl) {
                            durationEl.textContent = durMs + 'ms';
                            durationEl.style.display = 'inline-block';
                        }
                        if (outputEl) {
                            outputEl.className = 'warp-block-output out-success';
                            outputEl.style.whiteSpace = 'pre-wrap';
                            outputEl.textContent = seaportResult;
                        }

                        curTab.feed.push({
                            command: command,
                            output: seaportResult,
                            ok: true,
                            exit_code: 0,
                            duration_ms: durMs,
                            cwd: curTab.cwd,
                            timeStr: formatTimeNow(),
                            time: Date.now()
                        });
                        scrollFeedToBottom();
                        return;
                    }
                } catch (spErr) {
                    console.warn('[WarpTerminal] Error al procesar comando de puerto:', spErr);
                }
            }

            try {
                const res = await fetch(l8ApiUrl('api/bash/exec'), {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                        'X-L8-CSRF': '1'
                    },
                    body: JSON.stringify({ command: command, cwd: curTab.cwd })
                });
                const data = await res.json();
                const durMs = Math.round(performance.now() - startTime);

                const statusEl = block.querySelector('.warp-block-status');
                const statusLbl = block.querySelector('.status-label');
                const durationEl = block.querySelector('.warp-block-duration');
                const outputEl = block.querySelector('.warp-block-output');

                const isOk = !!data.ok;
                const outputText = isOk ? (data.stdout || '(Comando ejecutado con éxito sin salida)') : (data.stderr || data.error || 'Error al ejecutar comando');

                if (statusEl) {
                    statusEl.className = 'warp-block-status ' + (isOk ? 'success' : 'error');
                }
                if (statusLbl) {
                    statusLbl.textContent = isOk ? (data.exit_code !== undefined ? data.exit_code : '0') : (data.exit_code !== undefined ? data.exit_code : 'ERR');
                }
                if (durationEl) {
                    durationEl.textContent = (data.execution_time_ms || durMs) + 'ms';
                    durationEl.style.display = 'inline-block';
                }
                if (outputEl) {
                    outputEl.className = 'warp-block-output ' + (isOk ? 'out-success' : 'out-error');
                    outputEl.textContent = outputText;
                }

                if (data.display_path) {
                    curTab.cwd = data.display_path;
                    WarpTerminal.updateStatusPath(data.display_path);
                }

                curTab.feed.push({
                    command: command,
                    output: outputText,
                    ok: isOk,
                    exit_code: data.exit_code !== undefined ? data.exit_code : (isOk ? 0 : 1),
                    duration_ms: data.execution_time_ms || durMs,
                    cwd: curTab.cwd,
                    timeStr: formatTimeNow(),
                    time: Date.now()
                });
            } catch (e) {
                const durMs = Math.round(performance.now() - startTime);
                const statusEl = block.querySelector('.warp-block-status');
                const statusLbl = block.querySelector('.status-label');
                const outputEl = block.querySelector('.warp-block-output');
                const durationEl = block.querySelector('.warp-block-duration');

                if (statusEl) statusEl.className = 'warp-block-status error';
                if (statusLbl) statusLbl.textContent = 'ERR';
                if (durationEl) {
                    durationEl.textContent = durMs + 'ms';
                    durationEl.style.display = 'inline-block';
                }
                if (outputEl) {
                    outputEl.className = 'warp-block-output out-error';
                    outputEl.textContent = 'Error de conexión: ' + e.message;
                }

                curTab.feed.push({
                    command: command,
                    output: 'Error de conexión: ' + e.message,
                    ok: false,
                    exit_code: 'ERR',
                    duration_ms: durMs,
                    cwd: curTab.cwd,
                    timeStr: formatTimeNow(),
                    time: Date.now()
                });
            }
            scrollFeedToBottom();
        }
    };

    function renderTabs() {
        const containers = document.querySelectorAll('.warp-tabs-container');
        containers.forEach(container => {
            container.innerHTML = '';
            tabs.forEach(tab => {
                const isActive = tab.id === activeTabId;
                const tabEl = document.createElement('div');
                tabEl.className = 'warp-tab-item' + (isActive ? ' active' : '');
                tabEl.setAttribute('data-tab-id', tab.id);
                tabEl.title = tab.title;
                tabEl.onclick = () => window.selectWarpTab(tab.id);
                tabEl.innerHTML = `
                    <span class="warp-tab-icon">${SVG_ICONS[tab.icon] || SVG_ICONS.nodejs}</span>
                    <span class="warp-tab-title">${escapeHtml(tab.title)}</span>
                    <button type="button" class="warp-tab-close" title="Cerrar pestaña" onclick="window.closeWarpTab('${tab.id}', event)">&times;</button>
                `;
                container.appendChild(tabEl);
            });

            const addBtn = document.createElement('button');
            addBtn.type = 'button';
            addBtn.className = 'warp-add-tab-btn';
            addBtn.id = 'warpAddTabBtn';
            addBtn.title = 'Nueva pestaña';
            addBtn.textContent = '+';
            addBtn.onclick = (e) => {
                e.stopPropagation();
                window.createWarpTab();
            };
            container.appendChild(addBtn);
        });
    }

    window.createWarpTab = function (title) {
        tabCounter++;
        const newId = 'tab-' + tabCounter;
        const defaultNames = ['bash', 'node.js', 'bash 2', 'node.js 2', 'bash 3', 'node.js 3'];
        const tabTitle = title || (defaultNames[tabCounter - 1] || ('bash ' + tabCounter));
        tabs.push({
            id: newId,
            title: tabTitle,
            icon: 'nodejs',
            feed: [],
            history: [],
            cwd: '~/workspace'
        });
        window.selectWarpTab(newId);
    };

    window.selectWarpTab = function (tabId) {
        activeTabId = tabId;
        renderTabs();
        renderActiveFeed();
        const tab = getActiveTab();
        historyIndex = tab.history.length;
        const pathEl = document.getElementById('warpStatusPath');
        if (pathEl) pathEl.textContent = tab.cwd || '~/workspace';
        const inp = document.getElementById('warpCmdInput');
        if (inp) {
            inp.value = '';
            inp.focus();
        }
    };

    window.closeWarpTab = function (tabId, event) {
        if (event) event.stopPropagation();
        const index = tabs.findIndex(t => t.id === tabId);
        if (index === -1) return;
        tabs.splice(index, 1);
        if (tabs.length === 0) {
            tabCounter = 1;
            const newId = 'tab-1';
            tabs.push({
                id: newId,
                title: 'bash',
                icon: 'nodejs',
                feed: [],
                history: [],
                cwd: '~/workspace'
            });
            activeTabId = newId;
        } else if (activeTabId === tabId) {
            activeTabId = tabs[Math.max(0, index - 1)].id;
        }
        renderTabs();
        renderActiveFeed();
    };

    
    function formatTimeNow() {
        const now = new Date();
        return now.toTimeString().split(' ')[0];
    }

    function createBlockElement(cmd, cwd, isRunning) {
        const block = document.createElement('div');
        block.className = 'warp-block-card';
        block.innerHTML = `
            <div class="warp-block-header">
                <div class="warp-block-header-left">
                    <span class="warp-block-status ${isRunning ? 'running' : 'success'}">
                        <span class="warp-block-dot"></span>
                        <span class="status-label">${isRunning ? 'RUNNING' : '0'}</span>
                    </span>
                    <span class="warp-block-cwd">${escapeHtml(cwd || '~/workspace')}</span>
                    <span class="warp-block-time">${formatTimeNow()}</span>
                    <span class="warp-block-duration" style="${isRunning ? 'display:none;' : ''}"></span>
                </div>
                <div class="warp-block-actions">
                    <button type="button" class="warp-block-action-btn" title="Copiar salida" onclick="copyBlockOutput(this)">Copiar</button>
                    <button type="button" class="warp-block-action-btn" title="Re-ejecutar" onclick="window.WarpTerminal && window.WarpTerminal.executeCommand('${escapeHtml(cmd)}')">Re-ejecutar</button>
                </div>
            </div>
            <div class="warp-block-prompt-line">
                <span class="warp-block-prompt-symbol">&gt;</span>
                <span class="warp-block-cmd-text">${escapeHtml(cmd)}</span>
            </div>
            <div class="warp-block-output ${isRunning ? 'out-running' : 'out-success'}">${isRunning ? 'Ejecutando en Bash 4.3 + Python Catalyst...' : ''}</div>
        `;
        return block;
    }

    window.copyBlockOutput = function(btn) {
        const card = btn.closest('.warp-block-card');
        if (!card) return;
        const out = card.querySelector('.warp-block-output');
        if (out) {
            navigator.clipboard.writeText(out.innerText || out.textContent);
            const oldTxt = btn.textContent;
            btn.textContent = '¡Copiado!';
            setTimeout(() => { btn.textContent = oldTxt; }, 1500);
        }
    };

    function renderActiveFeed() {
        const tab = getActiveTab();
        const feed = document.getElementById('warpTerminalFeed');
        const placeholder = document.getElementById('warpAmbientPlaceholder');
        if (!feed) return;
        feed.innerHTML = '';
        if (tab.feed && tab.feed.length > 0) {
            if (placeholder) {
                placeholder.classList.add('hidden');
                placeholder.style.display = 'none';
            }
            tab.feed.forEach(item => {
                const block = document.createElement('div');
                block.className = 'warp-block-card';
                block.innerHTML = `
                    <div class="warp-block-header">
                        <div class="warp-block-header-left">
                            <span class="warp-block-status ${item.ok ? 'success' : 'error'}">
                                <span class="warp-block-dot"></span>
                                <span class="status-label">${item.ok ? (item.exit_code !== undefined ? item.exit_code : '0') : 'ERR'}</span>
                            </span>
                            <span class="warp-block-cwd">${escapeHtml(item.cwd || tab.cwd || '~/workspace')}</span>
                            <span class="warp-block-time">${item.timeStr || ''}</span>
                            ${item.duration_ms ? `<span class="warp-block-duration">${item.duration_ms}ms</span>` : ''}
                        </div>
                        <div class="warp-block-actions">
                            <button type="button" class="warp-block-action-btn" title="Copiar salida" onclick="copyBlockOutput(this)">Copiar</button>
                            <button type="button" class="warp-block-action-btn" title="Re-ejecutar" onclick="window.WarpTerminal && window.WarpTerminal.executeCommand('${escapeHtml(item.command)}')">Re-ejecutar</button>
                        </div>
                    </div>
                    <div class="warp-block-prompt-line">
                        <span class="warp-block-prompt-symbol">&gt;</span>
                        <span class="warp-block-cmd-text">${escapeHtml(item.command)}</span>
                    </div>
                    <div class="warp-block-output ${item.ok ? 'out-success' : 'out-error'}">${escapeHtml(item.output)}</div>
                `;
                feed.appendChild(block);
            });
        } else {
            if (placeholder) {
                placeholder.classList.remove('hidden');
                placeholder.style.display = 'flex';
            }
        }
        scrollFeedToBottom();
    }

