    window.submitWarpInput = function () {
        const input = document.getElementById('warpCmdInput');
        if (!input) return;
        const cmd = input.value.trim();
        if (cmd) {
            WarpTerminal.executeCommand(cmd);
            input.value = '';
        }
    };

    window.openApiGatewayWindow = showApiGatewayWindow;
